import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.DXRWYp4X.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"全栈 × AI","text":"学完能面试，能上线，牛逼","tagline":"前端、后端、AI 工程、Agent 开发四线贯通，18 章打底 + 7 章长矛 = 地表最强候选人的证据链。","actions":[{"theme":"brand","text":"🚀 开始学习","link":"/01-JavaScript运行时"},{"theme":"alt","text":"🗺️ 路线图","link":"/roadmap.html"},{"theme":"alt","text":"🧠 D 级框架","link":"/19-深度分级框架"}]},"features":[{"icon":"🧱","title":"前端底座（D2–D3）","details":"JS/TS 深度 · 框架原理 · 工程化 · 浏览器网络性能——能审查 AI 的代码，能定位线上问题"},{"icon":"🖥️","title":"后端工程（D2–D3）","details":"Node 运行时 · 认证 · API · 数据库 · 系统设计——全栈标准，接口自己扛得住线上"},{"icon":"🤖","title":"AI 工程（D2–D3→D4）","details":"LLM/RAG · Agent/MCP · AI 原生 UI——把模型接进真实产品；往下走一层到推理与评估，是区分度的分水岭"},{"icon":"⚔️","title":"两把长矛（D4）","details":"AI 推理层（mini-vLLM/LoRA 实证）+ 分布式内核（Raft/LSM/MQ）——造得出，才能讲到底"},{"icon":"📊","title":"证据链（D5）","details":"真实用户数字 + 项目复盘 + 开源 PR + 技术写作 —— 让实力被市场看得见"},{"icon":"🎯","title":"算法军械库（门票）","details":"100 天轨道 → medium 20min AC 率 >70% —— 没有这个，八股再好也过不了一面"}],"head":[["link",{"rel":"canonical","href":"https://R2h1.github.io/fullstack-learning-site/"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"全栈 × AI 学习路径"}],["meta",{"property":"og:description","content":"面试级 · 生产级 · 企业级的全栈 + AI 学习课程（个人笔记，内容优先）"}],["meta",{"property":"og:url","content":"https://R2h1.github.io/fullstack-learning-site/"}],["meta",{"name":"twitter:card","content":"summary"}]]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1793498840000}'),n={name:"index.md"};function o(i,t,l,v,s,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h2 id="📚-课程结构-18-章教材环" tabindex="-1" data-v-295e07e5>📚 课程结构（18 章教材环） <a class="header-anchor" href="#📚-课程结构-18-章教材环" aria-label="Permalink to &quot;📚 课程结构（18 章教材环）&quot;" data-v-295e07e5>​</a></h2><details class="details custom-block" data-v-295e07e5><summary data-v-295e07e5>点击展开完整目录</summary><ul data-v-295e07e5><li data-v-295e07e5><strong data-v-295e07e5>前端底座</strong>：01–05｜JS 运行时、TypeScript、框架原理、工程化、浏览器·网络·性能</li><li data-v-295e07e5><strong data-v-295e07e5>后端</strong>：06–13｜Node 运行时、HTTP 框架、认证授权、API 设计、后端工程化、数据库、缓存与分布式、系统设计</li><li data-v-295e07e5><strong data-v-295e07e5>AI</strong>：14–17｜AI 协作工作流、LLM 与 RAG、Agent 与 MCP、AI 原生 UI 与端侧</li><li data-v-295e07e5><strong data-v-295e07e5>面试</strong>：18｜手写题、八股、系统设计、项目深挖、90 天倒排</li></ul></details><div class="text-center" data-v-295e07e5><a href="/19-深度分级框架" class="vp-button brand" data-v-295e07e5>进入长矛区 →</a></div><h2 id="🗡️-长矛区-新增-7-章操练册" tabindex="-1" data-v-295e07e5>🗡️ 长矛区（新增 7 章操练册） <a class="header-anchor" href="#🗡️-长矛区-新增-7-章操练册" aria-label="Permalink to &quot;🗡️ 长矛区（新增 7 章操练册）&quot;" data-v-295e07e5>​</a></h2><p data-v-295e07e5>长矛不是「知识点」，而是「验收物」。你造出一件就离 D4 近一步，凑齐两把长矛 + 证据链就是地表 strongest candidate。</p><table tabindex="0" data-v-295e07e5><thead data-v-295e07e5><tr data-v-295e07e5><th data-v-295e07e5>新章</th><th data-v-295e07e5>交付物（验收标准）</th></tr></thead><tbody data-v-295e07e5><tr data-v-295e07e5><td data-v-295e07e5><strong data-v-295e07e5>19 · D 级分级框架</strong></td><td data-v-295e07e5>能用 D1–D5 给自己的每一项能力定坐标，并说出下一级的具体交付物</td></tr><tr data-v-295e07e5><td data-v-295e07e5><strong data-v-295e07e5>20 · 训练计划与里程碑</strong></td><td data-v-295e07e5>18–24 个月三阶段执行表；每月底 journal 复盘一次；20 章验收物清单填绿</td></tr><tr data-v-295e07e5><td data-v-295e07e5><strong data-v-295e07e5>21 · AI 模型层与推理优化</strong></td><td data-v-295e07e5>mini-GPT 实证 + LoRA 微调报告 + vLLM 压测 + mini-vLLM 调度器仓库（连续批处理 + KV Cache 分页）</td></tr><tr data-v-295e07e5><td data-v-295e07e5><strong data-v-295e07e5>22 · 分布式内核</strong></td><td data-v-295e07e5>mini-Raft（带正确性测试）+ miniLSM + minimq（at-least-once+死信队列）三件引擎仓库</td></tr><tr data-v-295e07e5><td data-v-295e07e5><strong data-v-295e07e5>23 · 项目实操册</strong></td><td data-v-295e07e5>项目一（SaaS 后端）：50+ 真实用户 + P99/QPS/成本三组数字 + 故障复盘文档<br data-v-295e07e5>项目二（RAG）：golden set 评估报告 + 红队安全报告 + 成本账单 + badcase 复盘</td></tr><tr data-v-295e07e5><td data-v-295e07e5><strong data-v-295e07e5>24 · 证据与影响力</strong></td><td data-v-295e07e5>≥1 个非 docs PR 被 merge + 10 篇深度文 + 简历三条 bullet 能被追问三层</td></tr><tr data-v-295e07e5><td data-v-295e07e5><strong data-v-295e07e5>25 · 算法军械库</strong></td><td data-v-295e07e5>100 题轨道（medium 20min AC 率 &gt;70%）；设计与并发池补强</td></tr></tbody></table><h3 id="为什么必须造这三样" tabindex="-1" data-v-295e07e5>为什么必须造这三样 <a class="header-anchor" href="#为什么必须造这三样" aria-label="Permalink to &quot;为什么必须造这三样&quot;" data-v-295e07e5>​</a></h3><ul data-v-295e07e5><li data-v-295e07e5><strong data-v-295e07e5>算法</strong>：国内大厂单程票，八股和作品再好都绕不过</li><li data-v-295e07e5><strong data-v-295e07e5>两个旗舰项目</strong>：「做过什么」不靠描述，靠 QPS/P99/成本/故障这些数字</li><li data-v-295e07e5><strong data-v-295e07e5>评估与安全</strong>：RAG 谁都会搭 demo，拼的是「检索质量怎么量化、幻觉怎么兜底」的工业级方法</li></ul><h2 id="🧩-如何读这本站" tabindex="-1" data-v-295e07e5>🧩 如何读这本站 <a class="header-anchor" href="#🧩-如何读这本站" aria-label="Permalink to &quot;🧩 如何读这本站&quot;" data-v-295e07e5>​</a></h2><table tabindex="0" data-v-295e07e5><thead data-v-295e07e5><tr data-v-295e07e5><th data-v-295e07e5>你的目标</th><th data-v-295e07e5>路径建议</th></tr></thead><tbody data-v-295e07e5><tr data-v-295e07e5><td data-v-295e07e5>前端转全栈，能面试</td><td data-v-295e07e5>01–18 → 20 章计划（前 9 个月）→ 25 章算法轨道</td></tr><tr data-v-295e07e5><td data-v-295e07e5>要拿头部 offer（D3→D4）</td><td data-v-295e07e5>01–18（L2/L3）并行 → 21/22/25 三把长矛（10–18 个月）→ 23 章项目收口 → 24 章证据链</td></tr><tr data-v-295e07e5><td data-v-295e07e5>要独立做出产品（营收验证）</td><td data-v-295e07e5>23 章项目一为主线 → 15/16/21 章按需补齐 → 每周公开迭代，真实用户反馈驱动</td></tr></tbody></table><blockquote data-v-295e07e5><p data-v-295e07e5>AGENTS.md 约定：内容保持通用教材定位，不绑定个人项目；长矛区和项目册是专门写给「要做出成果的人」的操练册，不受通用教材约束。</p></blockquote>',11)])])}const g=e(n,[["render",o],["__scopeId","data-v-295e07e5"]]);export{m as __pageData,g as default};
